@@ -0,0 +1,54 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const read=p=>JSON.parse(readFileSync(p,'utf8'));
+const review=read('docs/p9.0.6.3-final-semantic-review-ledger.json');
+const norm=read('docs/p9.0.6.1-normative-annex-ledger.json');
+const blocker=read('docs/p9.0.6-identity-unblock-matrix.json');
+const geo=read('docs/p9.0.6.2-verified-evidence-ledger.json');
+const historic=read('docs/p9.0.6.2.1-historical-evidence.json');
+const policy=read('docs/p9.0.4.3-promotion-policy.json');
+const release=read('data/current/actual-release-manifest.json');
+assert.equal(review.schema_version,'p9063-final-semantic-per-identity-review-v1');
+assert.equal(review.audit_date,'2026-10-15');
+assert.equal(review.main_source_sha,'61d869f9d124a8b8a57cc1a7524847e60947c2ca');
+const rows=review.rows;
+assert.equal(rows.length,85);
+assert.equal(new Set(rows.map(r=>r.actual_id)).size,85);
+const ids=new Set(norm.rows.map(r=>r.actual_id));
+const prev=new Set(blocker.rows.map(r=>r.actual_id));
+assert([...ids].every(id=>prev.has(id)));
+assert(rows.every(r=>ids.has(r.actual_id)));
+const counts=k=>rows.filter(x=>x.normative_2023_name_category===k).length;
+assert.equal(counts('UNIQUE_NAME_2023'),69);
+assert.equal(counts('HOMONYM_MULTIPLE_ENTRIES_2023'),11);
+assert.equal(counts('CURATED_ALIAS_POTENTIAL_MATCH'),4);
+assert.equal(counts('NO_EXACT_2023_NAME'),1);
+assert.equal(rows.filter(r=>r.source_2023_document_verified_by_official_annex).length,84);
+assert.equal(rows.filter(r=>r.polygon_geometry_2026_10_12_exact).length,85);
+const full=new Map(geo.rows.map(r=>['osm-r'+r.osm_id,r]));
+assert(rows.every(r=>full.get(r.actual_id)?.snapshot_polygon_status==='EXACT_COORDINATE_REPRESENTATION'));
+assert(rows.every(r=>full.get(r.actual_id)?.live_polygon_status==='EXACT_POLYGON_EDGES_261012_TO_LIVE'));
+assert.equal(historic.rows.length,84);
+assert.equal(historic.source_summary.status,'PASS');
+assert.equal(historic.source_summary.counts.unresolved,0);
+assert.equal(historic.source_summary.counts.spatial.disjoint,65);
+assert.equal(historic.source_summary.counts.spatial.boundary,19);
+assert.equal(review.sources.law114_2026.act_number,'114-ЗИД-VIII');
+assert.equal(review.sources.law114_2026.signed_pdf_sha256,'c9d05f579677f176007bd6987bf11031c986299e180d9e98577715f7cb1cc566');
+assert.equal(review.sources.law114_2026.operative_on_2026_10_15,false);
+assert.equal(review.sources.law114_2026.complete_compilation_of_all_annex_publications_verified,false);
+const crem=rows.find(r=>r.actual_id==='osm-r1216706');
+assert(crem);
+assert.equal(crem.geometric_parent_osm_id,'1702218');
+assert.equal(crem.claimed_administrative_parent_2023_single_hit?.osm_region_crosswalk_not_authoritative,'1702219');
+const lunga=rows.find(r=>r.actual_id==='osm-r19001619');
+assert(lunga);
+assert.equal(lunga.normative_2023_name_category,'NO_EXACT_2023_NAME');
+assert(rows.every(r=>r.full_polygon_effective_control_2026_certified===false&&r.independent_current_administrative_membership_2026_certified===false&&r.p91_import_allowed===false&&r.semantic_decision==='BLOCKED_INCOMPLETE'&&r.legal_md_parent_preservation_mandatory===true));
+assert.equal(review.decision.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(review.decision.p91_import_allowed,false);
+assert.equal(policy.p91_import_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(release.snapshot_id,'actual-a9e5a4ddcb5277ef');
+assert.equal(release.release_fingerprint_sha256,'a9e5a4ddcb5277ef614858c477be42bf1fe32e2ab1ca214ccad94fb9f42a6446');
+console.log('P9063_SEMANTIC_REVIEW_GATE_PASS: 85 reviewed, 85 geometry exact, 69/11/4/1 claims, 0 control certified, P9.1 DENIED');
